CREATE TABLE spike.events UUID '2ed0ba03-27bb-41a6-93da-0581520543d1' (`id` UInt64, `ts` DateTime DEFAULT now(), `user_id` UInt32 CODEC(Delta(4), ZSTD(3)), `payload` String DEFAULT '' CODEC(ZSTD(1)), `amount` Float64 DEFAULT 0, INDEX idx_user user_id TYPE minmax GRANULARITY 4) ENGINE = MergeTree PARTITION BY toYYYYMM(ts) ORDER BY id TTL ts + toIntervalYear(5) SETTINGS index_granularity = 8192